CREATE DATABASE IF NOT EXISTS ideare_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE ideare_db;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS design_item_options; DROP TABLE IF EXISTS design_items; DROP TABLE IF EXISTS designs;
DROP TABLE IF EXISTS handles; DROP TABLE IF EXISTS door_styles; DROP TABLE IF EXISTS colors; DROP TABLE IF EXISTS finishes; DROP TABLE IF EXISTS cabinet_templates; DROP TABLE IF EXISTS cabinet_categories;
SET FOREIGN_KEY_CHECKS=1;

CREATE TABLE cabinet_categories(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,slug VARCHAR(120) NOT NULL UNIQUE,description TEXT,sort_order INT DEFAULT 0,is_active BOOLEAN DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE cabinet_templates(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,category_id INT UNSIGNED,name VARCHAR(150) NOT NULL,slug VARCHAR(180) NOT NULL UNIQUE,description TEXT,preview_image VARCHAR(255),default_width DECIMAL(10,2) NOT NULL,default_height DECIMAL(10,2) NOT NULL,default_depth DECIMAL(10,2) NOT NULL,min_width DECIMAL(10,2) NOT NULL,max_width DECIMAL(10,2) NOT NULL,width_step DECIMAL(10,2) DEFAULT 50,min_height DECIMAL(10,2) NOT NULL,max_height DECIMAL(10,2) NOT NULL,height_step DECIMAL(10,2) DEFAULT 50,min_depth DECIMAL(10,2) NOT NULL,max_depth DECIMAL(10,2) NOT NULL,depth_step DECIMAL(10,2) DEFAULT 50,base_price DECIMAL(12,2) DEFAULT 0,sort_order INT DEFAULT 0,is_active BOOLEAN DEFAULT TRUE,FOREIGN KEY(category_id) REFERENCES cabinet_categories(id) ON DELETE SET NULL);
CREATE TABLE finishes(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,slug VARCHAR(120) UNIQUE,description TEXT,preview_image VARCHAR(255),price_modifier DECIMAL(12,2) DEFAULT 0,sort_order INT DEFAULT 0,is_active BOOLEAN DEFAULT TRUE);
CREATE TABLE colors(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,slug VARCHAR(120) UNIQUE,hex_code VARCHAR(20),texture_image VARCHAR(255),price_modifier DECIMAL(12,2) DEFAULT 0,sort_order INT DEFAULT 0,is_active BOOLEAN DEFAULT TRUE);
CREATE TABLE door_styles(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,slug VARCHAR(120) UNIQUE,description TEXT,preview_image VARCHAR(255),price_modifier DECIMAL(12,2) DEFAULT 0,sort_order INT DEFAULT 0,is_active BOOLEAN DEFAULT TRUE);
CREATE TABLE handles(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,slug VARCHAR(120) UNIQUE,description TEXT,preview_image VARCHAR(255),price_modifier DECIMAL(12,2) DEFAULT 0,sort_order INT DEFAULT 0,is_active BOOLEAN DEFAULT TRUE);
CREATE TABLE designs(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,design_code VARCHAR(50) NOT NULL UNIQUE,design_name VARCHAR(150),customer_name VARCHAR(150),customer_email VARCHAR(180),customer_phone VARCHAR(50),room_type VARCHAR(100),notes TEXT,total_width DECIMAL(12,2) DEFAULT 0,estimated_price DECIMAL(12,2) DEFAULT 0,status ENUM('draft','saved','submitted','quoted') DEFAULT 'draft',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE design_items(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,design_id INT UNSIGNED NOT NULL,cabinet_template_id INT UNSIGNED NOT NULL,finish_id INT UNSIGNED,color_id INT UNSIGNED,door_style_id INT UNSIGNED,handle_id INT UNSIGNED,position_order INT DEFAULT 0,width DECIMAL(10,2),height DECIMAL(10,2),depth DECIMAL(10,2),quantity INT DEFAULT 1,item_price DECIMAL(12,2) DEFAULT 0,FOREIGN KEY(design_id) REFERENCES designs(id) ON DELETE CASCADE,FOREIGN KEY(cabinet_template_id) REFERENCES cabinet_templates(id),FOREIGN KEY(finish_id) REFERENCES finishes(id),FOREIGN KEY(color_id) REFERENCES colors(id),FOREIGN KEY(door_style_id) REFERENCES door_styles(id),FOREIGN KEY(handle_id) REFERENCES handles(id));
CREATE TABLE design_item_options(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,design_item_id INT UNSIGNED NOT NULL,option_name VARCHAR(100) NOT NULL,option_value VARCHAR(150),price_modifier DECIMAL(12,2) DEFAULT 0,FOREIGN KEY(design_item_id) REFERENCES design_items(id) ON DELETE CASCADE);

